import os,sys,subprocess,json,time,shlex
from pathlib import Path
p=Path('/tmp/interval-refactor/rk-proposal')
results=[]
commands=[('native', 'cargo test --locked -p hyperinterval --all-features', {}), ('program', 'cargo test --locked -p hypersolve --all-features', {}), ('integration', 'cargo test --locked -p hyperdynamics -p hyperpath --all-features', {}), ('minimal', 'cargo test --locked -p hyperdynamics --no-default-features --features rk-proposal --test rk_proposal', {}), ('program-minimal', 'cargo test --locked -p hypersolve --no-default-features --features float-proposal-program --test program_float_proposal', {}), ('native-msrv', 'cargo +1.88.0 test --locked -p hyperinterval --no-default-features --features dyadic,float-proposal --test dyadic_float_ingress', {}), ('msrv', 'cargo +1.95.0 test --locked -p hyperdynamics --all-features --test rk_proposal --test field_construction_trace', {}), ('program-msrv', 'cargo +1.95.0 test --locked -p hypersolve --all-features --test program_float_proposal', {}), ('release', 'cargo test --locked --release -p hyperdynamics --all-features --test rk_proposal --test field_construction_trace --test evolution --test rational_time', {}), ('program-release', 'cargo test --locked --release -p hypersolve --all-features --test program_float_proposal', {}), ('native-release', 'cargo test --locked --release -p hyperinterval --all-features --test dyadic_float_ingress --test float', {}), ('clippy', 'cargo clippy --locked -p hyperinterval -p hypersolve -p hyperdynamics -p hyperpath --all-features --all-targets -- -D warnings', {}), ('default-off', 'cargo check --locked -p hyperdynamics -p hypersolve -p hyperinterval --no-default-features', {}), ('minimal-clippy', 'cargo clippy --locked -p hyperinterval --no-default-features --features dyadic,float-proposal --all-targets -- -D warnings', {}), ('docs', 'cargo doc --locked -p hyperinterval -p hypersolve -p hyperdynamics --all-features --no-deps', {'RUSTDOCFLAGS': '-D warnings'}), ('wasm', 'cargo check --locked -p hyperdynamics --all-features --target wasm32-unknown-unknown --lib', {}), ('native-embedded', 'cargo check --locked -p hyperinterval --no-default-features --features dyadic,float-proposal --target thumbv7em-none-eabihf --lib', {}), ('example', 'cargo run --locked -p hyperdynamics --features rk-proposal --example rk_proposal', {}), ('asan', 'cargo +nightly test --locked --target x86_64-unknown-linux-gnu -p hyperdynamics --all-features --test rk_proposal', {'RUSTFLAGS': '-Zsanitizer=address', 'CARGO_TARGET_DIR': '/tmp/interval-refactor/dyadic-evolution-asan'}), ('native-asan', 'cargo +nightly test --locked --target x86_64-unknown-linux-gnu -p hyperinterval --all-features --test dyadic_float_ingress', {'RUSTFLAGS': '-Zsanitizer=address', 'CARGO_TARGET_DIR': '/tmp/interval-refactor/dyadic-evolution-asan'}), ('program-asan', 'cargo +nightly test --locked --target x86_64-unknown-linux-gnu -p hypersolve --all-features --test program_float_proposal', {'RUSTFLAGS': '-Zsanitizer=address', 'CARGO_TARGET_DIR': '/tmp/interval-refactor/dyadic-evolution-asan'}), ('fmt', 'cargo fmt --all -- --check', {}), ('diff', 'git diff --check', {})]

for name,command,extra in commands:
 start=time.time()
 with (p/(name+'-final.log')).open('w') as log:
  run=subprocess.run(shlex.split(command),cwd='/mnt/development/csgrs',env={**os.environ,**extra},stdout=log,stderr=subprocess.STDOUT,timeout=900)
 results.append(dict(name=name,command=command,env=extra,returncode=run.returncode,seconds=time.time()-start,log=name+'-final.log'))
 (p/'checks-final.json').write_text(json.dumps(results,indent=2)+'\n')
 print(name,run.returncode,round(time.time()-start,2),flush=True)
 if run.returncode:sys.exit(run.returncode)
